          "advice": "Пример: HELP-392090 оставалась без движения 17 дней. В новой роли это уже не твоя личная недоработка, а риск для всего направления: про такую задачу вовремя не узнаёт ни заказчик, ни руководитель. Как отработать: заведи ежедневный контроль открытых заявок (10 минут утром) и правило «нет движения 3 дня — эскалация или переназначение». По каждой застрявшей задаче — короткий комментарий, что мешает и кто нужен для решения.",
