              "value": 0.5,
              "text": "Перегрузка и потеря деталей. Ты берёшь много задач на себя, и именно на деталях (комментарии, мелочи оформления) возникает просадка — руководитель отдельно отметил риск выгорания. Как отработать: разнеси нагрузку по приоритетам и не стесняйся делегировать то, что не требует именно твоей квалификации. Формула простая: меньше взятых задач — выше качество каждой."
